ob_start();
require_once 'header.php';
function createSlug($str){$unicode=['a'=>'á|à|ả|ã|ạ|ă|ắ|ặ|ằ|ẳ|ẵ|â|ấ|ầ|ẩ|ẫ|ậ','d'=>'đ','e'=>'é|è|ẻ|ẽ|ẹ|ê|ế|ề|ể|ễ|ệ','i'=>'í|ì|ỉ|ĩ|ị','o'=>'ó|ò|ỏ|õ|ọ|ô|ố|ồ|ổ|ỗ|ộ|ơ|ớ|ờ|ở|ỡ|ợ','u'=>'ú|ù|ủ|ũ|ụ|ư|ứ|ừ|ử|ữ|ự','y'=>'ý|ỳ|ỷ|ỹ|ỵ'];foreach($unicode as $nonUnicode=>$uni)$str=preg_replace("/($uni)/i",$nonUnicode,$str);$str=strtolower($str);$str=preg_replace('/[^a-z0-9\-]/','-',$str);return trim(preg_replace('/-+/','-',$str),'-');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){csrf_guard();$action=$_POST['action'];$id=preg_match('/^[0-9]+(-[0-9]+)?$/',(string)($_POST['id']??''))?(string)$_POST['id']:'';if($action==='remove'){if($id!==''&&isset($_SESSION['cart'][$id]))unset($_SESSION['cart'][$id]);}elseif($action==='update'){$qty=(int)$_POST['quantity'];if($id!==''&&isset($_SESSION['cart'][$id])){if($qty>0&&$qty<=$_SESSION['cart'][$id]['max_stock'])$_SESSION['cart'][$id]['quantity']=$qty;elseif($qty<=0)unset($_SESSION['cart'][$id]);}}header('Location: '.$base_url.'gio-hang');exit();}
$cart_items=$_SESSION['cart']??[];$total_price=0;foreach($cart_items as $item)$total_price+=$item['price']*$item['quantity'];
?>
<style>
.cart-page{padding:15px 0 60px}.cart-head{padding:17px 19px;margin-bottom:11px;border:1px solid var(--line);border-radius:14px;background:#fbfaf8;display:flex;align-items:center;justify-content:space-between;gap:15px}.cart-head h1{color:var(--primary-dark);font-size:27px}.cart-head p{margin-top:4px;color:var(--muted);font-size:14px}.cart-head i{font-size:30px;color:#c5aa91}.cart-layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:12px;align-items:start}.cart-summary{order:1;position:sticky;top:80px;border:1px solid var(--line);border-radius:13px;background:#fff;overflow:hidden}.cart-list{order:2;border:1px solid var(--line);border-radius:13px;background:#fff;overflow:hidden}.cart-list-title,.summary-head{padding:13px 15px;border-bottom:1px solid var(--line);background:#fff}.cart-list-title h2,.summary-head h2{color:var(--primary-dark);font-size:17px}.cart-list-title p,.summary-head p{margin-top:3px;color:var(--muted);font-size:13px}.cart-item{padding:11px 13px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:112px minmax(0,1fr) 128px 115px 34px;gap:11px;align-items:center}.cart-item:last-child{border-bottom:0}.cart-image{width:112px;height:92px;border-radius:9px;background:#fbfaf8;display:block;padding:5px}.cart-image img{width:100%;height:100%;object-fit:contain}.cart-info h3{color:var(--primary-dark);font-size:15px}.cart-info small{display:block;margin-top:5px;color:var(--muted);font-size:12px}.cart-info small.cart-variant{color:var(--primary);font-weight:bold}.unit-price{font-weight:bold;color:var(--primary-dark);font-size:14px}.qty-control{height:35px;border:1px solid var(--line);border-radius:8px;display:grid;grid-template-columns:32px 1fr 32px;overflow:hidden}.qty-btn{border:0;background:#fff;color:var(--primary);cursor:pointer}.qty-input{width:100%;border:0;text-align:center;outline:0}.line-total{color:var(--primary-dark);font-weight:bold}.btn-remove{width:32px;height:32px;border:1px solid #efd2ce;border-radius:8px;background:#fff;color:#ad5b55;cursor:pointer}.summary-body{padding:14px}.summary-row{padding:9px 0;display:flex;justify-content:space-between;gap:10px;color:var(--muted);border-bottom:1px solid var(--line)}.summary-row strong{color:var(--primary-dark)}.summary-row.total{font-size:16px;border-bottom:0}.summary-note{margin:10px 0;padding:9px;border-radius:8px;background:var(--soft);color:var(--muted);font-size:13px;line-height:1.45}.btn-checkout,.btn-continue{height:40px;border-radius:8px;display:flex;align-items:center;justify-content:center;gap:7px;font-weight:bold}.btn-checkout{border:0;background:var(--primary);color:#fff;width:100%;cursor:pointer}.btn-continue{margin-top:7px;border:1px solid var(--line);background:#fff;color:var(--primary-dark)}.empty-cart{padding:55px;text-align:center;border:1px solid var(--line);border-radius:13px}.empty-cart i{font-size:38px;color:#c5aa91}.empty-cart h2{margin:10px 0;color:var(--primary-dark)}@media(max-width:980px){.cart-layout{grid-template-columns:1fr}.cart-summary{order:2;position:static}.cart-list{order:1}}@media(max-width:720px){.cart-item{grid-template-columns:88px 1fr;gap:8px}.cart-image{width:88px;height:78px}.unit-price,.form-update-qty,.line-total,.btn-remove{grid-column:2}.form-update-qty{width:120px}}
</style>
<div class="container cart-page"><div class="breadcrumb"><a href="<?php echo $base_url; ?>"><i class="fas fa-home"></i> Trang chủ</a><i class="fas fa-chevron-right"></i><span>Giỏ hàng</span></div><section class="cart-head"><div><h1>Giỏ hàng của bạn</h1><p>Kiểm tra sản phẩm, số lượng và tổng tiền trước khi thanh toán.</p></div><span><i class="fas fa-cart-shopping"></i>&nbsp; <?php echo count($cart_items); ?> sản phẩm</span></section><?php if(empty($cart_items)):?><div class="empty-cart"><i class="fas fa-cart-shopping"></i><h2>Giỏ hàng đang trống</h2><p>Chọn sản phẩm sản phẩm công nghệ phù hợp rồi quay lại đây để đặt hàng.</p><a href="<?php echo $base_url; ?>san-pham">Xem sản phẩm</a></div><?php else:?><div class="cart-layout"><section class="cart-list"><div class="cart-list-title"><strong>Sản phẩm đã chọn</strong><span>Cập nhật số lượng trực tiếp</span></div><?php foreach($cart_items as $id=>$item):$pid=$item['product_id']??$id;$productUrl=$base_url.'san-pham/'.createSlug($item['name']).'-'.$pid;?><article class="cart-item"><a class="cart-image" href="<?php echo $productUrl; ?>"><img src="<?php echo htmlspecialchars(media_url($item['image'] ?? '', $base_url)); ?>" alt="<?php echo htmlspecialchars($item['name']); ?>"></a><div class="cart-info"><a href="<?php echo $productUrl; ?>"><h3><?php echo htmlspecialchars($item['name']); ?></h3></a><?php if(!empty($item['variant_name'])):?><small class="cart-variant">Phiên bản: <?php echo htmlspecialchars($item['variant_name']); ?></small><?php endif;?><small>Còn tối đa <?php echo (int)$item['max_stock']; ?> sản phẩm trong kho</small><div class="unit-price"><?php echo number_format($item['price'],0,',','.'); ?> đ</div></div><form method="POST" class="form-update-qty"><?php echo csrf_field(); ?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?php echo htmlspecialchars($id); ?>"><div class="qty-control"><button type="button" class="qty-btn" onclick="updateQty(this,-1)"><i class="fas fa-minus"></i></button><input type="number" name="quantity" class="qty-input" value="<?php echo $item['quantity']; ?>" min="1" max="<?php echo $item['max_stock']; ?>" readonly><button type="button" class="qty-btn" onclick="updateQty(this,1)"><i class="fas fa-plus"></i></button></div></form><div class="line-total"><?php echo number_format($item['price']*$item['quantity'],0,',','.'); ?> đ</div><button type="button" class="btn-remove" onclick="confirmRemove('<?php echo htmlspecialchars($id, ENT_QUOTES); ?>')"><i class="fas fa-trash"></i></button></article><?php endforeach;?></section><aside class="cart-summary"><div class="summary-head"><h2>Tóm tắt đơn hàng</h2><p>Tổng tiền được tính theo giỏ hàng hiện tại.</p></div><div class="summary-body"><div class="summary-row"><span>Tạm tính</span><strong><?php echo number_format($total_price,0,',','.'); ?> đ</strong></div><div class="summary-row"><span>Phí vận chuyển</span><strong>Miễn phí</strong></div><div class="summary-row total"><span>Tổng thanh toán</span><strong><?php echo number_format($total_price,0,',','.'); ?> đ</strong></div><div class="summary-note"><i class="fas fa-shield-halved"></i> Có thể chọn COD hoặc VNPay ở bước thanh toán.</div><?php if(isset($_SESSION['user_id'])):?><a href="<?php echo $base_url; ?>thanh-toan" class="btn-checkout"><i class="fas fa-credit-card"></i> Tiến hành thanh toán</a><?php else:?><button type="button" class="btn-checkout" onclick="requireLogin()"><i class="fas fa-right-to-bracket"></i> Đăng nhập để mua</button><?php endif;?><a href="<?php echo $base_url; ?>san-pham" class="btn-continue"><i class="fas fa-arrow-left"></i> Xem thêm sản phẩm công nghệ</a></div></aside></div><?php endif;?></div><form id="removeForm" method="POST" style="display:none"><?php echo csrf_field(); ?><input type="hidden" name="action" value="remove"><input type="hidden" name="id" id="removeId"></form><script>function updateQty(btn,change){const form=btn.closest('form'),input=form.querySelector('.qty-input'),max=parseInt(input.getAttribute('max')),current=parseInt(input.value),next=current+change;if(next>=1&&next<=max){input.value=next;form.submit()}else if(next>max){Swal.fire({icon:'warning',title:'Vượt quá số lượng',text:'Chỉ còn '+max+' sản phẩm trong kho.',confirmButtonColor:'#9a7658'})}}function confirmRemove(id){Swal.fire({title:'Xóa sản phẩm?',text:'Bạn có chắc chắn muốn bỏ sản phẩm này khỏi giỏ hàng?',icon:'warning',showCancelButton:true,confirmButtonColor:'#b45c57',cancelButtonColor:'#8c817a',confirmButtonText:'Đồng ý',cancelButtonText:'Hủy'}).then(function(result){if(result.isConfirmed){document.getElementById('removeId').value=id;document.getElementById('removeForm').submit()}})}function requireLogin(){Swal.fire({title:'Yêu cầu đăng nhập',text:'Bạn cần đăng nhập để tiến hành thanh toán đơn hàng.',icon:'info',showCancelButton:true,confirmButtonColor:'#9a7658',cancelButtonColor:'#8c817a',confirmButtonText:'Đăng nhập ngay',cancelButtonText:'Đóng'}).then(function(result){if(result.isConfirmed)window.location.href='<?php echo $base_url; ?>dang-nhap'})}</script><?php require_once 'footer.php'; ?>
